sp = 'app_pojavlauncher/src/main/res/values/strings.xml'
s = open(sp, encoding='utf-8').read()
missing = ['curseforge_api_key', 'mcn_exit_confirm', 'modpack_install_download_failed', 'notification_permission_dialog_text', 'preference_controller_map_wiped', 'progresslayout_tasks_in_progress', 'runtime_error_install_failed', 'runtime_error_missing', 'runtime_error_title', 'search_modpack_error', 'search_modpack_no_result', 'social_media_invite', 'vml_err_detached', 'vml_err_exists', 'vml_err_inval', 'vml_err_nomem', 'vml_err_ok', 'vml_err_unknown', 'vml_err_version', 'vml_fail_create_runtime', 'vml_fail_find_hooks', 'vml_fail_find_hooks_native', 'vml_fail_insert_hooks', 'vml_fail_load_classpath', 'vml_fail_load_runtime', 'vml_fail_run_main', 'vml_huh', 'xerr_adult_verification', 'xerr_child', 'xerr_no_account', 'xerr_not_available', 'xerr_unknown']
for k in missing:
    assert 'name="' + k + '"' not in s, k
assert s.count('</resources>') == 1
add = '    <string name="curseforge_api_key" translatable="false">DUMMY</string>\n    <string name="mcn_exit_confirm">Are you sure want to force close?</string>\n    <string name="modpack_install_download_failed">Failed to download modpack files</string>\n    <string name="notification_permission_dialog_text">FearLauncher requires a permission to post notifications to prevent game/modpack downloads from stopping when you leave the app. Without this permission, Android may shut down your downloads when you put FearLauncher in background mode.</string>\n    <string name="preference_controller_map_wiped">The controller config has been wiped.</string>\n    <string name="progresslayout_tasks_in_progress">%d tasks in progress</string>\n    <string name="runtime_error_install_failed">Failed to install Java %d. Please check your Internet connection and try again.</string>\n    <string name="runtime_error_missing">Java %d is not yet installed. Please choose another compatible runtime or connect to the Internet to install it automatically.</string>\n    <string name="runtime_error_title">Runtime not available</string>\n    <string name="search_modpack_error">Failed to find modpacks</string>\n    <string name="search_modpack_no_result">No modpacks found</string>\n    <string name="social_media_invite" translatable="false">https://discord.gg/9xBZSNG3Uc</string>\n    <string name="vml_err_detached">Thread is detached from the Java VM</string>\n    <string name="vml_err_exists">The VM is already loaded</string>\n    <string name="vml_err_inval">Bad arguments</string>\n    <string name="vml_err_nomem">Out of RAM</string>\n    <string name="vml_err_ok">Success</string>\n    <string name="vml_err_unknown">Unknown error</string>\n    <string name="vml_err_version">Incompatible JNI version</string>\n    <string name="vml_fail_create_runtime">Failed to create the Java virtual machine: %s</string>\n    <string name="vml_fail_find_hooks">Failed to find hook targets. Check latestlog.txt f\u00f6r details</string>\n    <string name="vml_fail_find_hooks_native">Failed to find native hooks.</string>\n    <string name="vml_fail_insert_hooks">Failed to install hooks: %s</string>\n    <string name="vml_fail_load_classpath">Failed to load the classpath. Check latestlog.txt for details</string>\n    <string name="vml_fail_load_runtime">Failed to load the Java virtual machine: %s</string>\n    <string name="vml_fail_run_main">Failed to start the main class. Check latestlog.txt for details</string>\n    <string name="vml_huh">\\???</string>\n    <string name="xerr_adult_verification">An adult needs to verify your account.</string>\n    <string name="xerr_child">Your account is a child account, and needs to be added into a Family in order to log in.</string>\n    <string name="xerr_no_account">You don\'t seem to have an Xbox Live account. Please log in once on https://minecraft.net/ and try again.</string>\n    <string name="xerr_not_available">Xbox Live is not available in your country</string>\n    <string name="xerr_unknown">Unknown Xbox Live API error %d</string>\n'
s = s.replace('</resources>', add + '</resources>')
open(sp, 'w', encoding='utf-8', newline='').write(s)
import xml.etree.ElementTree as ET
ET.parse(sp)
print('MC5 OK: added', len(missing), 'strings')
